import{c as i,Q as a,j as t,m as o}from"./chunks/framework.rWdQudnF.js";const d=JSON.parse('{"title":"架构师-备考 案例分析-系统架构设计真题回顾","description":"","frontmatter":{"title":"架构师-备考 案例分析-系统架构设计真题回顾"},"headers":[],"relativePath":"案例分析/系统架构设计真题回顾.md","filePath":"案例分析/系统架构设计真题回顾.md","lastUpdated":null}'),r={name:"案例分析/系统架构设计真题回顾.md"};function e(n,l,s,u,h,c){return a(),t("div",null,[...l[0]||(l[0]=[o('<p>架构的基础知识更新到了 <a href="/arch-exam/综合知识/架构设计/">架构师-备考 架构设计</a>，这里更多是同步过来部分内容（作为案例复习）</p><h3 id="运行期-vs-开发期质量属性-【软件系统的质量属性】" tabindex="-1">运行期 vs 开发期质量属性 【软件系统的质量属性】 <a class="header-anchor" href="#运行期-vs-开发期质量属性-【软件系统的质量属性】" aria-label="Permalink to &quot;运行期 vs 开发期质量属性 【软件系统的质量属性】&quot;">​</a></h3><p>可以将软件系统的质量属性分为<strong>开发期质量属性</strong>和<strong>运行期质量属性</strong> 2个部分。</p><h4 id="开发期质量属性" tabindex="-1">开发期质量属性 <a class="header-anchor" href="#开发期质量属性" aria-label="Permalink to &quot;开发期质量属性&quot;">​</a></h4><p>1.开发期质量属性主要指在软件开发阶段所关注的质量属性，主要包含6个方面。</p><ul><li>(1)易理解性：指设计被开发人员理解的难易程度。</li><li>(2)可扩展性：软件因适应新需求或需求变化而增加新功能的能力，也称为灵活性。</li><li>(3)可重用性：指重用软件系统或某一部分的难易程度。</li><li>(4)可测试性：对软件测试以证明其满足需求规范的难易程度。</li><li>(5)可维护性：当需要修改缺陷、增加功能、提高质量属性时，识别修改点并实施修改的难易程度。</li><li>(6)可移植性：将软件系统从一个运行环境转移到另一个不同的运行环境的难易程度。</li></ul><h4 id="运行期质量属性" tabindex="-1">运行期质量属性 <a class="header-anchor" href="#运行期质量属性" aria-label="Permalink to &quot;运行期质量属性&quot;">​</a></h4><p>2.运行期质量属性主要指在软件运行阶段所关注的质量属性，主要包含7个方面。</p><ul><li>(1)性能：性能是指软件系统及时提供相应服务的能力，如速度、吞吐量和容量等的要求。</li><li>(2)安全性：指软件系统同时兼顾向合法用户提供服务，以及阻止非授权使用的能力。</li><li>(3)可伸缩性：指当用户数和数据量增加时，软件系统维持高服务质量的能力。例如，通过增加服务器来提高能力。</li><li>(4)互操作性：指本软件系统与其他系统交换数据和相互调用服务的难易程度。</li><li>(5)可靠性：软件系统在一定的时间内持续无故障运行的能力。</li><li>(6)可用性：指系统在一定时间内正常工作的时间所占的比例。可用性会受到系统错误，恶意攻击，高负载等问题的影响。</li><li>(7)鲁棒性：是指软件系统在非正常情况（如用户进行了非法操作、相关的软硬件系统发生了故障等)下仍能够正常运行的能力，也称健壮性或容错性。</li></ul><h3 id="面向架构评估的质量属性" tabindex="-1">面向架构评估的质量属性 <a class="header-anchor" href="#面向架构评估的质量属性" aria-label="Permalink to &quot;面向架构评估的质量属性&quot;">​</a></h3><blockquote><p>质量属性效用树、质量属性判断</p></blockquote><h4 id="性能-performance" tabindex="-1">性能（Performance） <a class="header-anchor" href="#性能-performance" aria-label="Permalink to &quot;性能（Performance）&quot;">​</a></h4><ul><li>系统的响应能力：响应时间（多久响应）、吞吐量（单位时间处理事件个数）</li><li>典型场景：&quot;并发 10 万用户时，请求响应时间 &lt; 3 秒&quot;</li><li>架构策略：<strong>资源调度</strong>、<strong>引入并发</strong>、增加计算资源</li></ul><h4 id="可靠性-reliability" tabindex="-1">可靠性（Reliability） <a class="header-anchor" href="#可靠性-reliability" aria-label="Permalink to &quot;可靠性（Reliability）&quot;">​</a></h4><blockquote><p>🎯 可靠性 = 在规定条件和时间内完成规定功能的能力，核心指标是 MTBF（平均失效间隔时间）。</p></blockquote><ul><li>在意外或错误使用情况下维持功能特性的能力</li><li>**MTTF（平均失效等待时间）**和 <strong>MTBF（平均失效间隔时间）</strong>：在失效率为常数且修复时间很短的情况下，<strong>MTTF 和 MTBF 几乎相等</strong></li><li>与可用性的区别：可靠性侧重&quot;不出错&quot;，可用性侧重&quot;出错后能恢复&quot;</li></ul><p>可靠性：是软件系统<strong>在应用或系统错误面前</strong>，在意外或错误使用的情况下维持软件系统的功能特性的基本能力。如MTTF、MTBF。设计策略：心跳、Pig/Echo、冗余、选举。</p><p>包括容错和健壮性。</p><h4 id="可用性-availability" tabindex="-1"><strong>可用性（Availability）</strong> <a class="header-anchor" href="#可用性-availability" aria-label="Permalink to &quot;**可用性（Availability）**&quot;">​</a></h4><ul><li>系统故障后<strong>恢复并继续提供服务</strong>的能力</li><li>指标：MTBF（故障间隔时间）、MTTR（修复时间）</li><li>典型场景：&quot;主站宕机后，10 秒内自动切换至备用站点&quot;</li><li>架构策略：<strong>心跳</strong>（故障检测）、<strong>主动冗余</strong>（主备切换）</li></ul><h4 id="安全性-security" tabindex="-1"><strong>安全性（Security）</strong> <a class="header-anchor" href="#安全性-security" aria-label="Permalink to &quot;**安全性（Security）**&quot;">​</a></h4><ul><li>抵御恶意攻击的能力</li><li>典型场景：&quot;防止 99% 黑客攻击&quot;、&quot;对恶意操作进行报警和记录&quot;</li><li>架构策略：<strong>追踪审计</strong>、<strong>检测攻击</strong>、<strong>权限控制</strong></li></ul><h4 id="可修改性-modifiability" tabindex="-1"><strong>可修改性（Modifiability）</strong> <a class="header-anchor" href="#可修改性-modifiability" aria-label="Permalink to &quot;**可修改性（Modifiability）**&quot;">​</a></h4><ul><li>定位修改点并实施修改的难易程度</li><li>典型场景：&quot;二次开发时间不超过 3 个月&quot;、&quot;功能调整不超过 1 人月&quot;</li><li>包含：可维护性、可扩展性、结构重构、可移植性</li><li>架构策略：<strong>抽象接口</strong>、<strong>信息隐藏</strong>、<strong>接口-实现分离</strong></li></ul><h4 id="功能性" tabindex="-1">功能性 <a class="header-anchor" href="#功能性" aria-label="Permalink to &quot;功能性&quot;">​</a></h4><p>功能性：是系统所能完成所期望的工作的能力。一项任务的完成需要系统中许多或大多数构件的相互协作。</p><h4 id="可变性-variability" tabindex="-1">可变性（Variability） <a class="header-anchor" href="#可变性-variability" aria-label="Permalink to &quot;可变性（Variability）&quot;">​</a></h4><blockquote><p>🎯 可变性 = 体系结构经扩充或变更成为新体系结构的能力。注意：归属为可修改性的子维度，但<strong>独立考察</strong>。</p></blockquote><ul><li>可修改性包含：可维护性、可扩展性、结构重构、可移植性</li><li>⚠️ 常见坑：可变性<strong>不属于</strong>可修改性的组成部分（它是并列概念）</li></ul><h4 id="互操作性" tabindex="-1">互操作性 <a class="header-anchor" href="#互操作性" aria-label="Permalink to &quot;互操作性&quot;">​</a></h4><p>互操作性：作为系统组成部分的软件不是独立存在的，经常与其他系统或自身环境相互作用。</p><p>为了支持互操作性，软件体系结构必须<strong>为外部可视的功能特性和数据结构</strong>提供精心设计的软件入口。</p><p>程序和用其他编程语言编写的软件系统的交互作用就是互操作性的问题，也影响应用的软件体系结构。</p><h3 id="质量属性场景六要素" tabindex="-1">质量属性场景六要素 <a class="header-anchor" href="#质量属性场景六要素" aria-label="Permalink to &quot;质量属性场景六要素&quot;">​</a></h3><blockquote><p>软件系统质量属性（Quality Attribute）是一个系统的可测量或可测试的属性，用来描述系统满足利益相关者需求的程度。</p></blockquote><p><strong>质量属性场景六要素：</strong></p><ol><li><strong>刺激源</strong>（Source）— 谁发出的刺激</li><li><strong>刺激</strong>（Stimulus）— 触发系统的事件</li><li><strong>环境</strong>（Environment）— 事件发生时的条件</li><li><strong>制品</strong>（Artifact）— 被影响的系统组成部分</li><li><strong>响应</strong>（Response）— 系统对刺激的反应行为</li><li><strong>响应度量</strong>（Response Measure）— 可量化的评估指标</li></ol><blockquote><p>简化三要素（场景最小描述）：<strong>刺激、环境、响应</strong></p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260519001012.png" alt="image.png"></p><h3 id="架构风格" tabindex="-1">架构风格 <a class="header-anchor" href="#架构风格" aria-label="Permalink to &quot;架构风格&quot;">​</a></h3><ul><li><p><a href="/arch-exam/综合知识/架构设计/架构风格与模式/常用架构风格/">架构师-备考 架构设计-常用架构风格</a></p></li><li><p>基本架构风格</p><ul><li>数据流风格</li><li>调用/返回风格</li><li>独立构件风格</li><li>虚拟机风格</li><li>仓库（数据共享）风格</li><li>闭环控制（过程控制）</li><li>C2体系结构</li></ul></li><li><p>层次结构风格</p><ul><li>两层C/S架构</li><li>三层C/S架构</li><li>三层B/S架构</li><li>混合架构</li></ul></li></ul><p>富互联网应用(RIA) MVC /MVP/MVVM 面向服务的架构SOA</p><ul><li>批处理风格</li><li>管道 - 过滤器</li><li>调用/返回风格</li><li>主程序/子程序</li><li>面向对象</li><li>层次结构</li><li>客户端/服务器架构风格</li><li>三层C/S 结构</li><li>以数据为中心的架构风格</li><li>仓库架构风格</li><li>黑板架构风格</li><li>虚拟机风格 <ul><li>解释器</li><li>给予规则的系统</li></ul></li><li>独立构建风格</li><li>进程通信</li><li>事件驱动系统（隐式调用）</li><li>1</li></ul><h3 id="质量属性效用树" tabindex="-1">质量属性效用树 <a class="header-anchor" href="#质量属性效用树" aria-label="Permalink to &quot;质量属性效用树&quot;">​</a></h3>',44)])])}const p=i(r,[["render",e]]);export{d as __pageData,p as default};
